int cal(int x,vector<int> &pref,vector<int>&v,int n) {
    int low=1,high=n-x;
    while(low<=high){
        int mid=(low+high)/2;
        int f=v[x+2*mid-1]+v[x+2*mid-2];
        int g=v[3*n-1-2*x-(mid-1)];
        // cout<<"f =  "<<mid<<" "<<f<<" "<<g<<endl;
        if(4*f>(3*f+3*g)) {
            low=mid+1;
        } else {
            high=mid-1;
        }
    }
    return high;
}

